// Shared helpers for ENG-2490 CDP scenarios.
export const cmd = async ({ client, json, vault }, id) =>
  client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:${id}`)});`);

export const openNote = async ({ client, json }, path, { selectFrom, selectTo } = {}) =>
  client.evaluate(`return (async () => {
    const leaf = app.workspace.getLeaf("tab");
    await leaf.openFile(app.vault.getAbstractFileByPath(${json(path)}), { state: { mode: "source" } });
    app.workspace.setActiveLeaf(leaf, { focus: true });
    const ed = leaf.view.editor; ed.focus();
    ${selectFrom ? `ed.setSelection(${json(selectFrom)}, ${json(selectTo)});` : ""}
    return true;
  })();`);

export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Real mouse input at CSS-pixel coordinates.
export const mouse = async ({ client }, type, x, y, extra = {}) =>
  client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", buttons: type === "mouseReleased" ? 0 : 1, clickCount: 1, ...extra });

export const move = async ({ client }, x, y, pressed = true) =>
  client.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y, button: pressed ? "left" : "none", buttons: pressed ? 1 : 0 });

export const click = async (ctx, x, y) => {
  await move(ctx, x, y, false);
  await mouse(ctx, "mousePressed", x, y);
  await mouse(ctx, "mouseReleased", x, y);
};

export const dblclick = async (ctx, x, y) => {
  await click(ctx, x, y);
  await mouse(ctx, "mousePressed", x, y, { clickCount: 2 });
  await mouse(ctx, "mouseReleased", x, y, { clickCount: 2 });
};

export const key = (code, key, vk, extra = {}) => ({ key, code, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk, ...extra });

// T2: ModifyNodeModal search popover position + title textarea auto-height.
import { cmd, openNote, sleep, key } from "./lib.mjs";

const TA = ".modal-container textarea[placeholder]";
const POP = ".modal-container .suggestion-container";
const LONG = "test " + "a long multi line title that keeps going ".repeat(8);

const geom = ({ client, json }) =>
  client.evaluate(`
    const ta = document.querySelectorAll(${json(".modal-container textarea")});
    const t = [...ta].find((el) => !el.readOnly && !el.className.includes("cursor-default")) || ta[ta.length - 1];
    const p = document.querySelector(${json(POP)});
    const tr = t?.getBoundingClientRect(); const pr = p?.getBoundingClientRect();
    return { hasTa: !!t, taH: t?.offsetHeight, taStyleH: t?.style.height, scrollH: t?.scrollHeight,
      pop: !!p, popPos: p && getComputedStyle(p).position,
      dTop: p && Math.round(pr.top - tr.bottom), dLeft: p && Math.round(pr.left - tr.left), dW: p && Math.round(pr.width - tr.width),
      items: p ? p.querySelectorAll(".suggestion-item").length : 0 };`);

const typeInTitle = async ({ client, json }, text) => {
  await client.evaluate(`
    const ta = [...document.querySelectorAll(${json(".modal-container textarea")})].find((el) => el.className.includes("bg-background-primary"));
    ta.focus(); return true;`);
  await client.typeText(text);
};

const openCreate = async (ctx, body, sel) => {
  const p = await ctx.writeNote("modal-scratch.md", body);
  await openNote(ctx, p, sel);
  await cmd(ctx, "create-discourse-node");
  await ctx.client.waitFor(`!!document.querySelector(${ctx.json(".modal-container textarea")})`, { label: "modal open" });
  await sleep(300);
};

export default [
  {
    name: "T2.1 popover sits under title",
    input: "Create discourse node (empty selection); type 'test'",
    expected: "popover position:fixed, top = textarea bottom + 4, same left/width",
    run: async (ctx) => {
      await openCreate(ctx, "scratch\n");
      await typeInTitle(ctx, "test");
      await ctx.client.waitFor(`!!document.querySelector(${ctx.json(POP)})`, { label: "popover" });
      await sleep(400);
      return geom(ctx);
    },
    expect: (a) => ({ pass: a.pop && a.popPos === "fixed" && a.dTop === 4 && a.dLeft === 0 && a.dW === 0, actual: JSON.stringify(a) }),
  },
  {
    name: "T2.2 popover follows grown textarea",
    input: "Create discourse node; type a long multi-line title starting 'test'",
    expected: "textarea grows (height == scrollHeight); popover top still = bottom + 4",
    run: async (ctx) => {
      await openCreate(ctx, "scratch\n");
      await typeInTitle(ctx, LONG);
      await sleep(600);
      return geom(ctx);
    },
    expect: (a) => ({
      pass: a.taH > 60 && Math.abs(parseInt(a.taStyleH) - a.scrollH) <= 2 && (!a.pop || (a.dTop === 4 && a.dLeft === 0)),
      actual: JSON.stringify(a),
    }),
  },
  {
    name: "T2.4 no popover in convert-current-page",
    input: "Convert current page to discourse node; type 'test'",
    expected: "no .suggestion-container",
    run: async (ctx) => {
      const p = await ctx.writeNote("convert-scratch.md", "body\n");
      await openNote(ctx, p);
      await cmd(ctx, "convert-current-page-to-discourse-node");
      await ctx.client.waitFor(`!!document.querySelector(".modal-container textarea")`, { label: "modal open" });
      await typeInTitle(ctx, " test");
      await sleep(800);
      return geom(ctx);
    },
    expect: (a) => ({ pass: a.hasTa && !a.pop, actual: JSON.stringify(a) }),
  },
  {
    name: "T2.5 auto-height on open with long selection, shrinks on delete",
    input: "Select a 300-char line; Create discourse node; then select-all + type 'x'",
    expected: "on open height == scrollHeight (multi-row); after replace it shrinks",
    run: async (ctx) => {
      const line = "word ".repeat(60).trim();
      await openCreate(ctx, line + "\n", { selectFrom: { line: 0, ch: 0 }, selectTo: { line: 0, ch: line.length } });
      const open = await geom(ctx);
      await ctx.client.evaluate(`
        const ta = [...document.querySelectorAll(".modal-container textarea")].find((el) => el.className.includes("bg-background-primary"));
        ta.focus(); ta.select(); return true;`);
      await ctx.client.typeText("x");
      await sleep(400);
      return { open, after: await geom(ctx) };
    },
    expect: (a) => ({
      pass: a.open.taH > 60 && Math.abs(parseInt(a.open.taStyleH) - a.open.scrollH) <= 2 && a.after.taH < a.open.taH,
      actual: `open h=${a.open.taH} style=${a.open.taStyleH} scroll=${a.open.scrollH}; after h=${a.after.taH}`,
    }),
  },
  {
    name: "T2.6 keyboard pick from popover",
    input: "Create discourse node; type 'test'; ArrowDown; Enter",
    expected: "item picked: textarea replaced by locked display, popover gone",
    run: async (ctx) => {
      await openCreate(ctx, "scratch\n");
      await typeInTitle(ctx, "test");
      await ctx.client.waitFor(`document.querySelectorAll(${ctx.json(POP + " .suggestion-item")}).length > 0`, { label: "items" });
      await sleep(300);
      await ctx.client.key(key("ArrowDown", "ArrowDown", 40));
      await ctx.client.key(key("Enter", "Enter", 13));
      await sleep(500);
      return ctx.client.evaluate(`return {
        pop: !!document.querySelector(${ctx.json(POP)}),
        titleTa: !![...document.querySelectorAll(".modal-container textarea")].find((el) => el.className.includes("bg-background-primary")),
        text: document.querySelector(".modal-container .modal-content")?.innerText.slice(0, 200) };`);
    },
    expect: (a) => ({ pass: !a.pop && !a.titleTa, actual: JSON.stringify(a) }),
  },
];

