// T3: RelationshipSection "You can link with" chips (compatibleNodeTypes effect).
import { cmd, openNote, sleep } from "./lib.mjs";

const NT = {
  evidence: "node_zPr4p680Cvs8QItPn4ZyP",
  source: "REDACTED",
  claim: "node_cPwy7vUeOLdF2fv49i-DC",
};
const fm = (id) => `---\nnodeTypeId: ${id}\n---\nbody\n`;

// Open note, open the context view, click "Add a new relation".
const openAdd = async (ctx, name, typeId) => {
  const { client } = ctx;
  const p = await ctx.writeNote(name, fm(typeId));
  await openNote(ctx, p);
  await sleep(300);
  await client.evaluate(`app.workspace.rightSplit.expand(); return true;`);
  const open = await client.evaluate(`return app.workspace.getLeavesOfType("discourse-context-view").length > 0;`);
  if (!open) await cmd(ctx, "toggle-discourse-context");
  await client.waitFor(`return !!app.workspace.getLeavesOfType("discourse-context-view")[0]?.view.containerEl.querySelector("button")`, { label: "context view" });
  await sleep(500);
  await client.evaluate(`
    const root = app.workspace.getLeavesOfType("discourse-context-view")[0].view.containerEl;
    const b = [...root.querySelectorAll("button")].find((x) => x.textContent.trim() === "Add a new relation");
    b.click(); return true;`);
  await client.waitFor(`return !!app.workspace.getLeavesOfType("discourse-context-view")[0].view.containerEl.querySelector(".relationship-type-selector select")`, { label: "type select" });
  await sleep(300);
};

const state = ({ client }) =>
  client.evaluate(`
    const root = app.workspace.getLeavesOfType("discourse-context-view")[0].view.containerEl;
    const sel = root.querySelector(".relationship-type-selector select");
    const hint = [...root.querySelectorAll("span")].find((s) => s.textContent.startsWith("You can link with"));
    return { value: sel?.value ?? null, options: sel ? [...sel.options].map((o) => o.value) : [],
      chips: hint ? [...hint.querySelectorAll("span")].map((s) => s.textContent) : [] };`);

const pick = async ({ client, json }, label) => {
  await client.evaluate(`
    const sel = app.workspace.getLeavesOfType("discourse-context-view")[0].view.containerEl.querySelector(".relationship-type-selector select");
    sel.value = ${json(label)}; sel.dispatchEvent(new Event("change")); return true;`);
  await sleep(400);
};

export default [
  {
    name: "T3.1 chips for picked relation type (sidebar)",
    input: "Evidence note → context view → Add a new relation → pick 'informs'",
    expected: "chips = [Question]",
    run: async (ctx) => {
      await openAdd(ctx, "evidence-fixture.md", NT.evidence);
      const before = await state(ctx);
      await pick(ctx, "informs");
      return { before, after: await state(ctx) };
    },
    expect: (a) => ({ pass: a.before.chips.length === 0 && a.after.chips.join() === "Question", actual: JSON.stringify(a) }),
  },
  {
    name: "T3.2 chips update on switching type",
    input: "same; pick 'informs' then 'derived from'",
    expected: "chips Question → Source",
    run: async (ctx) => {
      await openAdd(ctx, "evidence-fixture.md", NT.evidence);
      await pick(ctx, "informs");
      const first = await state(ctx);
      await pick(ctx, "derived from");
      return { first: first.chips, second: (await state(ctx)).chips, options: first.options };
    },
    expect: (a) => ({ pass: a.first.join() === "Question" && a.second.join() === "Source", actual: JSON.stringify(a) }),
  },
  {
    name: "T3.3 single option auto-selects",
    input: "Source note → Add a new relation (only 'has derivation' applies)",
    expected: "type auto-selected; chips = [Evidence] without picking",
    run: async (ctx) => {
      await openAdd(ctx, "source-fixture.md", NT.source);
      await sleep(300);
      return state(ctx);
    },
    expect: (a) => ({ pass: a.chips.join() === "Evidence", actual: JSON.stringify(a) }),
  },
  {
    name: "T3.4 cancel then reopen clears chips",
    input: "Evidence note; pick 'informs'; Cancel; Add a new relation again",
    expected: "no chips after reopen",
    run: async (ctx) => {
      const { client } = ctx;
      await openAdd(ctx, "evidence-fixture.md", NT.evidence);
      await pick(ctx, "informs");
      await client.evaluate(`
        const root = app.workspace.getLeavesOfType("discourse-context-view")[0].view.containerEl;
        [...root.querySelectorAll("button")].find((x) => x.textContent.trim() === "Cancel").click(); return true;`);
      await sleep(300);
      await client.evaluate(`
        const root = app.workspace.getLeavesOfType("discourse-context-view")[0].view.containerEl;
        [...root.querySelectorAll("button")].find((x) => x.textContent.trim() === "Add a new relation").click(); return true;`);
      await sleep(400);
      return state(ctx);
    },
    expect: (a) => ({ pass: a.chips.length === 0 && a.value === "", actual: JSON.stringify(a) }),
  },
  {
    name: "T3.5 chips inside wikilink badge popover",
    input: "Live-preview note linking [[evidence-fixture]]; click its badge → Add a new relation → pick 'informs'",
    expected: "popover opens; chips = [Question]",
    run: async (ctx) => {
      const { client, json } = ctx;
      const ev = await ctx.writeNote("evidence-fixture.md", fm(NT.evidence));
      const base = ev.split("/").pop().replace(/\.md$/, "");
      const p = await ctx.writeNote("link-host.md", `see [[${base}]] here\n`);
      await client.evaluate(`return (async () => {
        const leaf = app.workspace.getLeaf("tab");
        await leaf.openFile(app.vault.getAbstractFileByPath(${json(p)}), { state: { mode: "source", source: false } });
        app.workspace.setActiveLeaf(leaf, { focus: true }); return true; })();`);
      const hasBadge = await client
        .waitFor(`return !!app.workspace.activeLeaf.view.containerEl.querySelector(".dg-discourse-context-badge")`, { label: "badge", timeoutMs: 6000 })
        .then(() => true, () => false);
      if (!hasBadge) return { hasBadge };
      await client.evaluate(`app.workspace.activeLeaf.view.containerEl.querySelector(".dg-discourse-context-badge").click(); return true;`);
      await client.waitFor(`return !!document.querySelector(".dg-discourse-context-popover")`, { label: "popover" });
      await sleep(400);
      await client.evaluate(`
        const root = document.querySelector(".dg-discourse-context-popover");
        [...root.querySelectorAll("button")].find((x) => x.textContent.trim() === "Add a new relation").click(); return true;`);
      await sleep(400);
      await client.evaluate(`
        const sel = document.querySelector(".dg-discourse-context-popover .relationship-type-selector select");
        sel.value = "informs"; sel.dispatchEvent(new Event("change")); return true;`);
      await sleep(400);
      return client.evaluate(`
        const root = document.querySelector(".dg-discourse-context-popover");
        const hint = [...root.querySelectorAll("span")].find((s) => s.textContent.startsWith("You can link with"));
        return { hasBadge: true, chips: hint ? [...hint.querySelectorAll("span")].map((s) => s.textContent) : [] };`);
    },
    expect: (a) => ({ pass: a.hasBadge && a.chips?.join() === "Question", actual: JSON.stringify(a) }),
    teardown: async ({ client }) => client.evaluate(`document.querySelectorAll(".dg-discourse-context-popover").forEach((e) => e.remove()); return true;`),
  },
  {
    name: "T3.6 chips react to relation settings change",
    input: "Evidence note, pick 'informs'; then add allowed triple Evidence-informs-Claim to settings + save",
    expected: "PARITY with main (record whether chips gain Claim without reopening)",
    setup: async ({ client }) => ({
      saved: await client.evaluate(`const p = app.plugins.plugins["@discourse-graph/obsidian"]; return JSON.stringify(p.settings.discourseRelations);`),
    }),
    run: async (ctx) => {
      const { client } = ctx;
      await openAdd(ctx, "evidence-fixture.md", NT.evidence);
      await pick(ctx, "informs");
      const before = (await state(ctx)).chips;
      await client.evaluate(`return (async () => {
        const p = app.plugins.plugins["@discourse-graph/obsidian"];
        const r0 = p.settings.discourseRelations.find((r) => r.relationshipTypeId === "relation_C2SEexDH9O4x1iJzitb2w");
        p.settings.discourseRelations = [...p.settings.discourseRelations, { ...r0, id: "verify-tmp", destinationId: ${JSON.stringify(NT.claim)} }];
        await p.saveSettings(); return true; })();`);
      await sleep(800);
      return { before, after: (await state(ctx)).chips };
    },
    expect: (a) => ({ pass: a.before.join() === "Question", actual: JSON.stringify(a) }),
    teardown: async ({ client }, { saved }) =>
      client.evaluate(`return (async () => { const p = app.plugins.plugins["@discourse-graph/obsidian"];
        p.settings.discourseRelations = JSON.parse(${JSON.stringify(saved)}); await p.saveSettings(); return true; })();`),
  },
];

// T4: useSchemaSelection reset-on-resetKey (export + import schema modals).
import { cmd, sleep } from "./lib.mjs";

const DIR = "/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/dad56eb0-85c8-43af-afe3-79e3dc24c31b/scratchpad/cdp/schema";
const A = `${DIR}/dg-schema-A.json`;
const B = `${DIR}/dg-schema-B.json`;

// Swap window.require("electron") so native open/save dialogs return fixed paths.
const stubDialogs = ({ client, json }) =>
  client.evaluate(`
    if (!window.__origRequire) window.__origRequire = window.require;
    window.__dgNextOpen = ${json(A)};
    window.require = (m) => {
      const real = window.__origRequire(m);
      if (m !== "electron") return real;
      const dialog = {
        showOpenDialog: async () => ({ canceled: false, filePaths: [window.__dgNextOpen] }),
        showSaveDialog: async () => ({ canceled: false, filePath: ${json(A)} }),
      };
      return { ...real, dialog, remote: { ...(real.remote || {}), dialog } };
    };
    return true;`);
const unstub = ({ client }) =>
  client.evaluate(`if (window.__origRequire) { window.require = window.__origRequire; delete window.__origRequire; } return true;`);

const sections = ({ client }) =>
  client.evaluate(`
    const m = document.querySelector(".modal-container");
    const out = {};
    for (const h of m.querySelectorAll("h4")) {
      const sec = h.parentElement.closest("div") ;
      const boxes = [...(h.closest("section") || h.parentElement.parentElement).querySelectorAll('input[type="checkbox"]')];
      out[h.textContent.trim()] = { checked: boxes.filter((b) => b.checked).length, total: boxes.length };
    }
    return out;`);

const clickText = ({ client, json }, text) =>
  client.evaluate(`
    const b = [...document.querySelectorAll(".modal-container button")].find((x) => x.textContent.trim() === ${json(text)});
    if (!b) return false; b.click(); return true;`);

export default [
  {
    name: "T4.1 export defaults + writes fixture A",
    input: "Export discourse graph schema modal; read checkboxes; Export (save dialog stubbed)",
    expected: "node/relation types + triples all checked; templates: only referenced ones",
    setup: async (ctx) => {
      require("node:fs").mkdirSync(DIR, { recursive: true });
      await stubDialogs(ctx);
      return {};
    },
    run: async (ctx) => {
      await cmd(ctx, "export-dg-schema");
      await ctx.client.waitFor(`return !!document.querySelector(".modal-container h4")`, { label: "export modal" });
      await sleep(500);
      const secs = await sections(ctx);
      await clickText(ctx, "Export schema");
      await sleep(1500);
      const fs = await import("node:fs");
      if (fs.existsSync(A)) fs.copyFileSync(A, B);
      return { secs, wrote: fs.existsSync(A) };
    },
    expect: (a) => {
      const s = a.secs;
      const full = (k) => s[k] && s[k].total > 0 && s[k].checked === s[k].total;
      return { pass: a.wrote && full("Node types") && full("Relation types") && full("Relation triples"), actual: JSON.stringify(a) };
    },
    teardown: async (ctx) => unstub(ctx),
  },
  {
    name: "T4.2 import selection resets on new file",
    input: "Import modal: pick A; uncheck 2 node types; Choose another file → B; then back to A",
    expected: "after B: all node types checked; after A again: all checked",
    setup: async (ctx) => {
      await stubDialogs(ctx);
      return {};
    },
    run: async (ctx) => {
      const { client, json } = ctx;
      await cmd(ctx, "import-dg-schema");
      await client.waitFor(`return !!document.querySelector(".modal-container button")`, { label: "import modal" });
      await clickText(ctx, "Choose schema file");
      await client.waitFor(`return !!document.querySelector(".modal-container h4")`, { label: "preview A" });
      await sleep(400);
      const fresh = await sections(ctx);
      await client.evaluate(`
        const h = [...document.querySelectorAll(".modal-container h4")].find((x) => x.textContent.trim() === "Node types");
        const boxes = [...(h.closest("section") || h.parentElement.parentElement).querySelectorAll('input[type="checkbox"]')];
        boxes.slice(0, 2).forEach((b) => b.click()); return true;`);
      await sleep(300);
      const unchecked = await sections(ctx);
      await client.evaluate(`window.__dgNextOpen = ${json(B)}; return true;`);
      await clickText(ctx, "Choose another file");
      await sleep(300);
      await clickText(ctx, "Choose schema file");
      await client.waitFor(`return !!document.querySelector(".modal-container h4")`, { label: "preview B" });
      await sleep(400);
      const afterB = await sections(ctx);
      await client.evaluate(`window.__dgNextOpen = ${json(A)}; return true;`);
      await clickText(ctx, "Choose another file");
      await sleep(300);
      await clickText(ctx, "Choose schema file");
      await client.waitFor(`return !!document.querySelector(".modal-container h4")`, { label: "preview A again" });
      await sleep(400);
      return { fresh: fresh["Node types"], unchecked: unchecked["Node types"], afterB: afterB["Node types"], afterA: (await sections(ctx))["Node types"] };
    },
    expect: (a) => ({
      pass: a.fresh.checked === a.fresh.total && a.unchecked.checked === a.fresh.total - 2 && a.afterB.checked === a.afterB.total && a.afterA.checked === a.afterA.total,
      actual: JSON.stringify(a),
    }),
    teardown: async (ctx) => unstub(ctx),
  },
  {
    name: "T4.3 re-pick same path keeps or resets selection",
    input: "Import: pick A; uncheck 2 node types; Choose another file → A again",
    expected: "PARITY with main (record checked count)",
    setup: async (ctx) => {
      await stubDialogs(ctx);
      return {};
    },
    run: async (ctx) => {
      const { client } = ctx;
      await cmd(ctx, "import-dg-schema");
      await client.waitFor(`return !!document.querySelector(".modal-container button")`, { label: "import modal" });
      await clickText(ctx, "Choose schema file");
      await client.waitFor(`return !!document.querySelector(".modal-container h4")`, { label: "preview A" });
      await sleep(400);
      await client.evaluate(`
        const h = [...document.querySelectorAll(".modal-container h4")].find((x) => x.textContent.trim() === "Node types");
        const boxes = [...(h.closest("section") || h.parentElement.parentElement).querySelectorAll('input[type="checkbox"]')];
        boxes.slice(0, 2).forEach((b) => b.click()); return true;`);
      await sleep(300);
      await clickText(ctx, "Choose another file");
      await sleep(300);
      await clickText(ctx, "Choose schema file");
      await client.waitFor(`return !!document.querySelector(".modal-container h4")`, { label: "preview A again" });
      await sleep(400);
      return (await sections(ctx))["Node types"];
    },
    expect: (a) => ({ pass: !!a, actual: JSON.stringify(a) }),
    teardown: async (ctx) => unstub(ctx),
  },
  {
    name: "T4.4 rapid toggles, no render loop",
    input: "Export modal; toggle every node-type checkbox 3x quickly",
    expected: "no 'Too many re-renders' / max update depth errors; final state all checked",
    run: async (ctx) => {
      const { client } = ctx;
      await client.evaluate(`window.__dgErr = []; window.__dgOrigErr = console.error;
        console.error = (...a) => { window.__dgErr.push(String(a[0]).slice(0, 120)); window.__dgOrigErr(...a); }; return true;`);
      await cmd(ctx, "export-dg-schema");
      await client.waitFor(`return !!document.querySelector(".modal-container h4")`, { label: "export modal" });
      await client.evaluate(`
        const h = [...document.querySelectorAll(".modal-container h4")].find((x) => x.textContent.trim() === "Node types");
        const boxes = () => [...(h.closest("section") || h.parentElement.parentElement).querySelectorAll('input[type="checkbox"]')];
        for (let i = 0; i < 6; i++) boxes().forEach((b) => b.click()); return true;`);
      await sleep(600);
      const s = (await sections(ctx))["Node types"];
      const errs = await client.evaluate(`console.error = window.__dgOrigErr; return window.__dgErr.filter((e) => /render|update depth/i.test(e));`);
      return { s, errs };
    },
    expect: (a) => ({ pass: a.errs.length === 0 && a.s.checked === a.s.total, actual: JSON.stringify(a) }),
  },
];

