export const NT = { evidence: "node_zPr4p680Cvs8QItPn4ZyP", claim: "node_cPwy7vUeOLdF2fv49i-DC" };
export const fm = (id, body = "body") => `---\nnodeTypeId: ${id}\n---\n${body}\n`;

export const readState = () => (fs.existsSync(STATE) ? JSON.parse(fs.readFileSync(STATE, "utf8")) : {});
export const writeState = (s) => fs.writeFileSync(STATE, JSON.stringify(s, null, 2));

// Expose the tldraw editor of the active canvas leaf as window.__dgEditor.
export const grabEditor = ({ client }) =>
  client.waitFor(`
    const root = app.workspace.activeLeaf?.view?.containerEl;
    const c = root?.querySelector(".tl-canvas");
    if (!c) return false;
    const k = Object.keys(c).find((x) => x.startsWith("__reactFiber$"));
    let f = c[k];
    while (f && !f.memoizedProps?.value?.putExternalContent) f = f.return;
    if (!f) return false;
    window.__dgEditor = f.memoizedProps.value;
    return true;`, { label: "tldraw editor" });

export const collapse = ({ client }) =>
  client.evaluate(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse(); return true;`);

// Create a fresh canvas (first call) or reopen the saved one, collapse sidebars, grab the editor.
export const openCanvas = async (ctx, { fresh = false } = {}) => {
  const { client, json } = ctx;
  const st = readState();
  if (fresh || !st.canvas) {
    await cmd(ctx, "create-discourse-graph-canvas");
    await client.waitFor(`return !!app.workspace.activeLeaf?.view?.containerEl.querySelector(".tl-canvas")`, { label: "canvas view" });
    st.canvas = await client.evaluate(`return app.workspace.activeLeaf.view.file.path;`);
    st.viewType = await client.evaluate(`return app.workspace.activeLeaf.view.getViewType();`);
    writeState(st);
  } else {
    await client.evaluate(`return (async () => {
      const leaf = app.workspace.getLeaf("tab");
      await leaf.setViewState({ type: ${json(st.viewType)}, state: { file: ${json(st.canvas)} }, active: true });
      app.workspace.setActiveLeaf(leaf, { focus: true }); return true; })();`);
    await client.waitFor(`return !!app.workspace.activeLeaf?.view?.containerEl.querySelector(".tl-canvas")`, { label: "canvas view" });
  }
  await collapse(ctx);
  await sleep(600);
  await grabEditor(ctx);
  return st;
};

export const shapes = ({ client }) =>
  client.evaluate(`const ed = window.__dgEditor; return ed.getCurrentPageShapes().map((s) => ({ id: s.id, type: s.type, x: s.x, y: s.y, index: s.index, parentId: s.parentId, props: s.props }));`);

// Page point -> viewport (CSS px) point for real mouse input.
export const toScreen = ({ client, json }, p) =>
  client.evaluate(`const ed = window.__dgEditor; const s = ed.pageToScreen(${json(p)}); return { x: s.x, y: s.y };`);

export const centerOf = ({ client, json }, id) =>
  client.evaluate(`const ed = window.__dgEditor; const b = ed.getShapePageBounds(${json(id)}); const s = ed.pageToScreen({ x: b.midX, y: b.midY }); return { x: s.x, y: s.y };`);

export const dropNode = async ({ client, json }, path, point) =>
  client.evaluate(`return (async () => {
    const ed = window.__dgEditor;
