    await ed.putExternalContent({ type: "url", url, point: ${json(point)} });
    return true; })();`);

export const consoleTrap = ({ client }) =>
  client.evaluate(`window.__dgErr = []; if (!window.__dgOrigErr) window.__dgOrigErr = console.error;
    console.error = (...a) => { window.__dgErr.push(a.map(String).join(" ").slice(0, 200)); window.__dgOrigErr(...a); };
